Tactic Notation "callZc" uconstr(SPEC) tactic3(CLR) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) => eapply evt_cut; [ eapply SPEC | CLR; post_callZ segs m ]
  end.
