Definition P_PB_RET : Z := 0x34b04.       (* [comment removed for export] *)

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition PREP_SEG1_STACK : Z := 192.

(* [comment removed for export] *)
Definition alloc_frame (m : mem) (a : Z) (j48 : list byte) (n : Z) : Prop :=
  rw_cells rsegs m a [CB 48 j48; C8 (wz n); C8 (wz P_PB_RET)].

Definition prep_seg1_post (sp : word) (gp tp s10 s11 : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) (fc : bv 32) (res b : Z) (es : list mbe) (insz n lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s4 s8 t3 t4 t5 t6 m' j24 j48 oe1,
    ms' = MS (mkR (wz P_ALLOC_RET) (wz (bv_unsigned sp - 192)) gp tp t0 t1 t2 (wz (mb_grow es insz n)) (wz res)
                  (wz (mb_block_size (mb_grow es insz n))) a1 a2 a3 a4 a5 a6 a7 (wz b) (wz (b + 8)) s4 (wz (mb_cap es))
                  (wz (insz + n - mb_cap es)) (wz 0) s8 (wz 0) s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (b + 56, b + 64)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp - 192)
    /\ prep_frame m' (bv_unsigned sp - 128) j24 (wz (bv_unsigned sp - 104)) (wz (bv_unsigned sp - 104)) s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav
    /\ alloc_frame m' (bv_unsigned sp - 192) j48 n
    /\ MBraw m' b es (mb_out b es insz) insz (mb_outpos es insz) oe1.

Definition prep_seg1_stmt : Prop := forall (res b : Z) (es : list mbe) (insz n lo : Z)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  MBuf m b es insz -> mb_need es insz n = true -> 1 <= n -> insz + n <= 2^30 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + PREP_SEG1_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= b -> bv_unsigned sp mod 16 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (prep_seg1_post sp gp tp s10 s11 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra F fc res b es insz n lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz b) (wz n) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MB_PREPARE) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Definition at_c94 (x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 : word) (g : Z) (x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 : word,
    ms' = MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 (wz g) a2 a3 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
             F (Z_to_bv 64 0x34afc) fc None m (seg_rom rsegs).

Lemma shl1_small : forall x, 0 <= x < 2^62 -> Z.land (Z.shiftl x 1) 18446744073709551615 = 2 * x.
Proof.
  intros x Hx. rewrite Z.shiftl_mul_pow2 by lia. change 18446744073709551615 with (Z.ones 64).
  rewrite Z.land_ones by lia. rewrite Z.mod_small by lia. lia.
Qed.
