Lemma prep_size_policy : forall (x1 x2 x3 x4 x5 x6 x7 x8 x9 : word) (insz total nrem : Z) (a2 a3 : word)
    (x14 x15 x16 x17 x18 x19 x20 : word) (x23 x24 x25 x26 x27 x28 x29 x30 x31 : word) (F : bvmap 5 word) fc (m : mem),
  0 <= insz -> 1 <= nrem -> insz + nrem <= 2^30 -> 0 <= total <= 2^40 ->
  mem_inv rsegs m ->
  evt rsegs (at_c94 x1 x2 x3 x4 x5 x6 x7 x8 x9 (wz insz) (Z.max nrem (Z.max 512 (2 * insz))) x14 x15 x16 x17 x18 x19 x20
               (wz total) (wz nrem) x23 x24 x25 x26 x27 x28 x29 x30 x31 F fc m)
    (MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (wz insz) (wz MB_MAX) a2 a3 x14 x15 x16 x17 x18 x19 x20 (wz total) (wz nrem) x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 0x34ad8) fc None m (seg_rom rsegs)).
